@OptIn(ExperimentalMaterial3Api::class) @Composable fun SalesRoute(onBack:()->Unit,onImport:(String)->Unit,vm:SalesImportListViewModel=hiltViewModel()){
 val s by vm.state.collectAsStateWithLifecycle();val picker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){it?.let(vm::select)};val pick={picker.launch(arrayOf("application/json","text/json","text/plain"))};val snack=remember{SnackbarHostState()};val success=stringResource(R.string.sales_import_success)
 LaunchedEffect(s.success){if(s.success){snack.showSnackbar(success);vm.consumeSuccess()}}
 Scaffold(snackbarHost={AppSnackbarHost(snack)},topBar={TopAppBar(title={Text(stringResource(R.string.sales_title))},navigationIcon={TextButton(onClick=onBack){Text(stringResource(R.string.action_back))}})}){p->when{s.loading->Centered(p){CircularProgressIndicator()};s.noRestaurant->Centered(p){SalesErrorState(stringResource(R.string.sales_load_error))};else->LazyColumn(Modifier.padding(p).adaptiveContentWidth(960.dp),contentPadding=PaddingValues(AppSpacing.md),verticalArrangement=Arrangement.spacedBy(AppSpacing.md)){item{AppSectionHeader(stringResource(R.string.sales_history),subtitle=stringResource(R.string.sales_history_support),trailing={ImportButton(pick,!s.busy)})};if(s.imports.isEmpty())item{EmptySales(pick,!s.busy)}else items(s.imports,key={it.exportId}){x->SalesHistoryCard(x){onImport(x.exportId)}};if(s.busy&&s.prepared==null)item{BusyRow()}}}}
 s.prepared?.let{SalesImportPreview(it,s.busy,vm::dismiss,vm::confirm)}
 s.duplicate?.let{x->AlertDialog(onDismissRequest=vm::dismiss,icon={AppStatusChip(stringResource(R.string.sales_duplicate_status),StatusTone.INFO)},title={Text(stringResource(R.string.sales_duplicate_title))},text={Column(verticalArrangement=Arrangement.spacedBy(AppSpacing.sm)){InfoRow(stringResource(R.string.sales_business_date),dateFmt.format(x.businessDate));InfoRow(stringResource(R.string.sales_imported_label),dateTimeFmt.format(x.importedAt))}},confirmButton={TextButton(onClick={vm.dismiss();onImport(x.exportId)}){Text(stringResource(R.string.sales_view_import))}},dismissButton={TextButton(onClick=vm::dismiss){Text(stringResource(R.string.action_cancel))}})}
 s.error?.let{e->AlertDialog(onDismissRequest=vm::dismiss,icon={AppStatusChip(stringResource(if(e.serious())R.string.sales_error_status else R.string.sales_attention_status),if(e.serious())StatusTone.ERROR else StatusTone.WARNING)},title={Text(stringResource(R.string.sales_import_problem))},text={Text(stringResource(e.message()))},confirmButton={TextButton(onClick=vm::dismiss){Text(stringResource(android.R.string.ok))}})}
}
