@OptIn(ExperimentalMaterial3Api::class) @Composable fun SalesImportDetailRoute(onBack:()->Unit,onTransaction:(String,String)->Unit,vm:SalesImportDetailViewModel=hiltViewModel()){
 val s by vm.state.collectAsStateWithLifecycle()
 Scaffold(topBar={TopAppBar(title={Text(stringResource(R.string.sales_import_detail))},navigationIcon={TextButton(onClick=onBack){Text(stringResource(R.string.action_back))}})}){p->
  when{
   s.loading->Centered(p){CircularProgressIndicator()}
   s.error||s.detail==null->Centered(p){SalesErrorState(stringResource(R.string.sales_import_load_error),vm::retry)}
   else->BoxWithConstraints(Modifier.fillMaxSize().padding(p)){val d=s.detail!!;if(maxWidth>=760.dp)Row(Modifier.fillMaxSize().adaptiveContentWidth(1200.dp).padding(AppSpacing.md),horizontalArrangement=Arrangement.spacedBy(AppSpacing.lg)){Column(Modifier.width(340.dp),verticalArrangement=Arrangement.spacedBy(AppSpacing.lg)){SalesImportSummary(d.salesImport,s.summary!!);SalesAudit(d.salesImport)};TransactionList(d.transactions,onTransaction,Modifier.weight(1f))}else LazyColumn(Modifier.adaptiveContentWidth(760.dp),contentPadding=PaddingValues(AppSpacing.md),verticalArrangement=Arrangement.spacedBy(AppSpacing.lg)){item{SalesImportSummary(d.salesImport,s.summary!!)};item{AppSectionHeader(stringResource(R.string.sales_transactions))};items(d.transactions){x->TransactionRow(x){onTransaction(x.transaction.terminalId,x.transaction.transactionId)}};item{SalesAudit(d.salesImport)}}}
  }
 }
}
@Composable private fun SalesImportSummary(x:SalesImport,s:SalesSummary){Column(verticalArrangement=Arrangement.spacedBy(AppSpacing.sm)){AppSectionHeader(stringResource(R.string.sales_import_summary));Text(dateFmt.format(x.businessDate),style=MaterialTheme.typography.headlineSmall);Text(x.terminalId,style=MaterialTheme.typography.titleMedium);Text(stringResource(R.string.sales_imported,dateTimeFmt.format(x.importedAt)),color=MaterialTheme.colorScheme.onSurfaceVariant);Text(stringResource(R.string.sales_revision_currency,x.publicationRevision,x.currency),color=MaterialTheme.colorScheme.onSurfaceVariant);AppCard(Modifier.fillMaxWidth()){Column(Modifier.padding(AppSpacing.md),verticalArrangement=Arrangement.spacedBy(AppSpacing.sm)){Metric(stringResource(R.string.sales_completed),s.completed.toString());Metric(stringResource(R.string.sales_voided),s.voided.toString());Metric(stringResource(R.string.sales_transactions),s.transactions.toString());HorizontalDivider();Metric(stringResource(R.string.sales_gross),Formatters.formatCurrency(s.gross,x.currency));Metric(stringResource(R.string.sales_discounts),Formatters.formatCurrency(s.discount,x.currency));Metric(stringResource(R.string.sales_net),Formatters.formatCurrency(s.net,x.currency),true)}}}}
