@Composable private fun TransactionRow(d:ImportedSaleTransactionDetail,onClick:()->Unit){val x=d.transaction;AppCard(Modifier.fillMaxWidth().clickable(onClick=onClick)){Row(Modifier.padding(AppSpacing.md).fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(AppSpacing.md)){Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(AppSpacing.xs)){Text(timeFmt.format(x.openedAt),style=MaterialTheme.typography.titleMedium);AppStatusChip(status(x.status),if(x.status==ImportedSaleStatus.COMPLETED)StatusTone.SUCCESS else StatusTone.NEUTRAL);Text(stringResource(R.string.sales_line_count,d.lines.size),color=MaterialTheme.colorScheme.onSurfaceVariant)};Text(Formatters.formatCurrency(d.lines.fold(BigDecimal.ZERO){a,l->a+l.net},x.currency),style=MaterialTheme.typography.titleMedium)}}}
